    """Split text on SEP characters that are not inside quotes."""
    fields = []
    current = []
    quoted = False
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == QUOTE:
            if quoted and i + 1 < len(text) and text[i + 1] == QUOTE:
                current.append(QUOTE)
                current.append(QUOTE)
                i += 2
                continue
            quoted = not quoted
            current.append(ch)
        elif ch == SEP and not quoted:
            fields.append("".join(current))
            current = []
        else:
            current.append(ch)
        i += 1
    if quoted:
        raise ValueError("unclosed quote")
    fields.append("".join(current))
    return fields


def _separator_index(field):
    """Return the index of the first '=' outside quotes, or -1."""
    quoted = False
    i = 0
    while i < len(field):
        ch = field[i]
        if ch == QUOTE:
            if quoted and i + 1 < len(field) and field[i + 1] == QUOTE:
                i += 2
                continue
            quoted = not quoted
        elif ch == "=" and not quoted:
            return i
        i += 1
    return -1


