    """Trim an unquoted value, or unwrap and unescape a quoted one."""
    text = text.strip()
    if not text.startswith(QUOTE):
        if QUOTE in text:
            raise ValueError(f"quote in unquoted value: {text!r}")
        return text
    out = []
    i = 1
    while i < len(text):
        ch = text[i]
        if ch == QUOTE:
            if i + 1 < len(text) and text[i + 1] == QUOTE:
                out.append(QUOTE)
                i += 2
                continue
            if text[i + 1:].strip():
                raise ValueError(f"junk after quoted value: {text!r}")
            return "".join(out)
        out.append(ch)
        i += 1
    raise ValueError(f"unclosed quote: {text!r}")


